reference.setup:
{
    ref_curve <- function(x, p) p[1] + (p[2] - p[1])/(1 + 10^((p[3] - x) * p[4]))
    ref_jacobian <- function(x, p) {
        sapply(1:4, function(j) {
            h <- 1e-04
            at <- function(k) {
                q <- p
                q[j] <- p[j] + k * h
                ref_curve(x, q)
            }
            (at(-2) - 8 * at(-1) + 8 * at(1) - at(2))/(12 * h)
        })
    }
    ref_runs <- function(s) {
        n1 <- sum(s > 0)
        n2 <- sum(s < 0)
        r <- 1 + sum(s[-1] != s[-length(s)])
        m <- 2 * n1 * n2/(n1 + n2) + 1
        v <- (m - 1) * (m - 2)/(n1 + n2 - 1)
        z <- (r - m)/sqrt(v)
        list(ran = TRUE, n_runs = r, n_pos = n1, n_neg = n2, z = z, p = 2 * pnorm(-abs(z)))
    }
    ref_optimum <- function(x, y, start = NULL, lower = rep(-Inf, 4), upper = rep(Inf, 
        4), w = rep(1, length(x))) {
        sw <- sqrt(w)
        fixed <- lower == upper
        best <- c(Inf, NA, NA, NA, NA)
        if (!is.null(start)) 
            best <- c(0, start)
        hills <- c(-seq(0.1, 5, by = 0.05), seq(0.1, 5, by = 0.05))
        if (fixed[4]) 
            hills <- lower[4]
        else hills <- hills[hills >= lower[4] & hills <= upper[4]]
        if (is.null(start)) 
            for (l in seq(min(x), max(x), length.out = 41)) {
                for (h in hills) {
                  f <- 1/(1 + 10^((l - x) * h))
                  X <- cbind(1 - f, f)
                  co <- c(lower[1], lower[2])
                  free <- !fixed[1:2]
                  if (any(free)) {
                    fit <- qr.coef(qr(sw * X[, free, drop = FALSE]), sw * (y - X[, 
                      !free, drop = FALSE] %*% co[!free]))
                    if (any(!is.finite(fit))) 
                      next
                    co[free] <- pmin(pmax(fit, lower[1:2][free]), upper[1:2][free])
                  }
                  rss <- sum(w * (y - X %*% co)^2)
                  if (rss < best[1]) 
                    best <- c(rss, co, l, h)
                }
            }
        p <- unname(best[2:5])
        p <- pmin(pmax(p, lower), upper)
        rss <- function(p) sum(w * (y - ref_curve(x, p))^2)
        lm <- function(p, idx) {
            lambda <- 0.001
            for (it in 1:1000) {
                J <- sw * ref_jacobian(x, p)[, idx, drop = FALSE]
                A <- crossprod(J)
                step <- unname(drop(solve(A + lambda * diag(diag(A), length(idx)), 
                  crossprod(J, sw * (y - ref_curve(x, p))))))
                q <- p
                q[idx] <- pmin(pmax(p[idx] + step, lower[idx]), upper[idx])
                if (rss(q) <= rss(p)) {
                  moved <- max(abs(q - p)/pmax(abs(q), 1e-08))
                  p <- q
                  lambda <- lambda/10
                  if (moved < 1e-14) 
                    break
                }
                else {
                  lambda <- lambda * 10
                }
                if (lambda > 1e+12) 
                  break
            }
            p
        }
        idx <- which(!fixed)
        p <- lm(p, idx)
        idx <- which(!fixed & p > lower & p < upper)
        p <- lm(p, idx)
        for (it in 1:5) {
            J <- sw * ref_jacobian(x, p)[, idx, drop = FALSE]
            p[idx] <- p[idx] + unname(drop(qr.coef(qr(J), sw * (y - ref_curve(x, 
                p)))))
        }
        if (all(is.infinite(c(lower, upper))) && p[1] > p[2]) 
            p <- c(p[2], p[1], p[3], -p[4])
        p
    }
    ref_param <- function(value, se, t, dependency) {
        list(value = value, status = "fitted", se = se, lower = value - t * se, upper = value + 
            t * se, dependency = dependency, ambiguous = dependency > 0.9999)
    }
    ref_held <- function(value, status) list(value = value, status = status, ambiguous = FALSE)
    limits <- function(bottom = NULL, top = NULL, hill = NULL) {
        one <- function(v) {
            if (is.null(v)) 
                return(c(-Inf, Inf))
            if (length(v) == 1) 
                return(c(v, v))
            c(if (is.na(v[1])) -Inf else v[1], if (is.na(v[2])) Inf else v[2])
        }
        b <- one(bottom)
        t <- one(top)
        h <- one(hill)
        list(lower = c(b[1], t[1], -Inf, h[1]), upper = c(b[2], t[2], Inf, h[2]))
    }
    ref_interpolate <- function(y0, p, half, span, back) {
        res <- function(status, x = NA_real_, lower = NA_real_, upper = NA_real_) {
            list(y = y0, status = status, x = x, lower = lower, upper = upper)
        }
        f <- (y0 - p[1])/(p[2] - p[1])
        if (f <= 0) 
            return(res("beyond-bottom"))
        if (f >= 1) 
            return(res("beyond-top"))
        reach <- 5 * max(span, 1)
        xh <- uniroot(function(v) ref_curve(v, p) - y0, p[3] + c(-1, 1) * 30/abs(p[4]), 
            tol = 1e-14)$root
        edge <- function(sgn, dir) {
            fun <- function(v) ref_curve(v, p) + sgn * half(v) - y0
            v <- xh + dir * reach * (0:2000)/2000
            s0 <- sign(fun(v))
            hit <- which(s0[-1] != s0[1])
            if (length(hit) == 0) 
                return(NA_real_)
            uniroot(fun, sort(v[hit[1] + 0:1]), tol = 1e-13)$root
        }
        rising <- (p[2] - p[1]) * p[4] > 0
        lo <- edge(if (rising) 
            1
        else -1, -1)
        hi <- edge(if (rising) 
            -1
        else 1, 1)
        res("ok", back(xh), back(lo), back(hi))
    }
    run_fpl_one <- function(dose, y, log_x = TRUE, bounds = limits(), w = NULL, ypow = 0, 
        unknown = numeric(0)) {
        lower <- bounds$lower
        upper <- bounds$upper
        if (is.null(w)) 
            w <- rep(1, length(dose))
        dropped <- if (log_x) 
            0
        else sum(dose <= 0)
        if (!log_x) {
            y <- y[dose > 0]
            w <- w[dose > 0]
            dose <- dose[dose > 0]
        }
        x <- if (log_x) 
            dose
        else log10(dose)
        back <- if (log_x) 
            function(v) v
        else function(v) 10^v
        n <- length(x)
        fixed <- lower == upper
        p <- ref_optimum(x, y, lower = lower, upper = upper, w = w)
        if (ypow > 0) {
            for (it in 1:500) {
                w <- ref_curve(x, p)^-ypow
                q <- ref_optimum(x, y, start = p, lower = lower, upper = upper, w = w)
                moved <- max(abs(q - p)/pmax(abs(p), 1e-08))
                p <- q
                if (moved < 1e-13) 
                  break
            }
            w <- ref_curve(x, p)^-ypow
        }
        sw <- sqrt(w)
        idx <- which(!fixed & p > lower & p < upper)
        J <- sw * ref_jacobian(x, p)[, idx, drop = FALSE]
        A <- crossprod(J)
        Ainv <- solve(A)
        fitted <- ref_curve(x, p)
        resid <- y - fitted
        df <- n - length(idx)
        ss <- sum(w * resid^2)
        s2 <- ss/df
        se <- sqrt(s2 * diag(Ainv))
        dependency <- 1 - 1/(diag(A) * diag(Ainv))
        t <- qt(0.975, df)
        ord <- order(x)
        signs <- sign(resid[ord])
        grid <- seq(min(x), max(x), length.out = 100)
        half <- function(v) {
            G <- matrix(ref_jacobian(v, p), length(v))[, idx, drop = FALSE]
            t * sqrt(vapply(seq_along(v), function(i) drop(G[i, ] %*% Ainv %*% G[i, 
                ]), 0) * s2)
        }
        half_grid <- half(grid)
        w_new <- vapply(grid, function(v) w[which.min(abs(x - v))], 0)
        fit_grid <- ref_curve(grid, p)
        par <- function(i) {
            j <- match(i, idx)
            if (is.na(j)) 
                return(ref_held(p[i], if (fixed[i]) "fixed" else "at_bound"))
            ref_param(p[i], se[j], t, dependency[j])
        }
        j3 <- match(3, idx)
        list(n = n, dropped = dropped, ran = TRUE, bottom = par(1), top = par(2), 
            logec50 = par(3), hill = par(4), ec50 = 10^p[3], ec50_lower = 10^(p[3] - 
                t * se[j3]), ec50_upper = 10^(p[3] + t * se[j3]), df = df, ss = ss, 
            syx = sqrt(s2), r2 = 1 - ss/sum(w * (y - weighted.mean(y, w))^2), x = back(x[ord]), 
            y = y[ord], fitted = fitted[ord], residual = resid[ord], runs = ref_runs(signs[signs != 
                0]), band = list(x = back(grid), fit = fit_grid, confidence_lower = fit_grid - 
                half_grid, confidence_upper = fit_grid + half_grid, prediction_lower = fit_grid - 
                t * sqrt((half_grid/t)^2 + s2/w_new), prediction_upper = fit_grid + 
                t * sqrt((half_grid/t)^2 + s2/w_new)), unknowns = lapply(unknown, 
                function(y0) ref_interpolate(y0, p, half, diff(range(x)), back)))
    }
    run_fpl <- function(dose, y, log_x = TRUE, bounds = limits(), alt = NULL, w = NULL, 
        ypow = 0, unknown = numeric(0)) {
        fit <- run_fpl_one(dose, y, log_x, bounds, w, ypow, unknown)
        if (is.null(alt) || !isTRUE(fit$ran)) 
            return(fit)
        s <- run_fpl_one(dose, y, log_x, alt, w)
        n <- fit$n
        aicc <- function(ss, df) {
            k <- (n - df) + 1
            n * log(ss/n) + 2 * k + 2 * k * (k + 1)/(n - k - 1)
        }
        df_num <- s$df - fit$df
        f_test <- if (fit$ss <= 0) {
            list(ok = FALSE, why = "exact_fit")
        }
        else if (df_num < 1 || fit$df < 1) {
            list(ok = FALSE, why = "no_extra")
        }
        else {
            f <- ((s$ss - fit$ss)/df_num)/(fit$ss/fit$df)
            list(ok = TRUE, f = f, df_num = df_num, df_den = fit$df, p = pf(f, df_num, 
                fit$df, lower.tail = FALSE))
        }
        k_fit <- (n - fit$df) + 1
        k_alt <- (n - s$df) + 1
        a <- if (n - k_fit - 1 <= 0 || n - k_alt - 1 <= 0 || fit$ss <= 0) {
            list(ok = FALSE)
        }
        else {
            a_fit <- aicc(fit$ss, fit$df)
            a_alt <- aicc(s$ss, s$df)
            w <- exp(-0.5 * (c(a_fit, a_alt) - min(a_fit, a_alt)))
            list(ok = TRUE, fit = a_fit, simpler = a_alt, prob_fit = w[1]/sum(w), 
                prob_simpler = w[2]/sum(w))
        }
        fit$comparison <- list(ran = TRUE, simpler = list(bottom = s$bottom$value, 
            top = s$top$value, logec50 = s$logec50$value, hill = s$hill$value, ec50 = s$ec50, 
            ss = s$ss, df = s$df), f_test = f_test, aicc = a)
        fit
    }
    ref_compare <- function(cx, sm, n, nested = TRUE) {
        aicc <- function(ss, df) {
            k <- (n - df) + 1
            n * log(ss/n) + 2 * k + 2 * k * (k + 1)/(n - k - 1)
        }
        df_num <- sm$df - cx$df
        f_test <- if (!nested) {
            list(ok = FALSE, why = "not_nested")
        }
        else if (cx$ss <= 0) {
            list(ok = FALSE, why = "exact_fit")
        }
        else if (df_num < 1 || cx$df < 1) {
            list(ok = FALSE, why = "no_extra")
        }
        else {
            f <- ((sm$ss - cx$ss)/df_num)/(cx$ss/cx$df)
            list(ok = TRUE, f = f, df_num = df_num, df_den = cx$df, p = pf(f, df_num, 
                cx$df, lower.tail = FALSE))
        }
        k_cx <- (n - cx$df) + 1
        k_sm <- (n - sm$df) + 1
        a <- if (n - k_cx - 1 <= 0 || n - k_sm - 1 <= 0 || cx$ss <= 0) {
            list(ok = FALSE)
        }
        else {
            a_cx <- aicc(cx$ss, cx$df)
            a_sm <- aicc(sm$ss, sm$df)
            w <- exp(-0.5 * (c(a_cx, a_sm) - min(a_cx, a_sm)))
            list(ok = TRUE, fit = a_cx, simpler = a_sm, prob_fit = w[1]/sum(w), prob_simpler = w[2]/sum(w))
        }
        list(f_test = f_test, aicc = a)
    }
    run_fpl_models <- function(dose, y, log_x = TRUE, bounds = limits(), other = limits(), 
        role = 1) {
        fa <- run_fpl_one(dose, y, log_x, bounds)
        fb <- run_fpl_one(dose, y, log_x, other)
        cx <- if (role == 2) 
            fb
        else fa
        sm <- if (role == 2) 
            fa
        else fb
        st <- ref_compare(cx, sm, fa$n, role != 3)
        fa$comparison <- list(ran = TRUE, simpler = list(bottom = sm$bottom$value, 
            top = sm$top$value, logec50 = sm$logec50$value, hill = sm$hill$value, 
            ec50 = sm$ec50, ss = sm$ss, df = sm$df), f_test = st$f_test, aicc = st$aicc)
        fa
    }
    run_global_models <- function(dose, y, g, shared, other_shared, log_x = TRUE, 
        bounds = limits(), other = bounds, role = 1, w = NULL) {
        fa <- run_global(dose, y, g, shared, log_x, bounds, w)
        fb <- run_global(dose, y, g, other_shared, log_x, other, w)
        cx <- if (role == 2) 
            fb$global
        else fa$global
        sm <- if (role == 2) 
            fa$global
        else fb$global
        st <- ref_compare(cx, sm, fa$global$n, role != 3)
        fa$comparison <- list(ran = TRUE, simpler = list(ss = sm$ss, df = sm$df), 
            f_test = st$f_test, aicc = st$aicc)
        fa
    }
}
